contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We'll take two deposit amounts and a flag to optionally call withdrawAll in-between.
    // The idea: record credit before an action by making a zero-value deposit to read prior credit via observable behavior,
    // then perform the intermediate actions, then read credit after and assert it never increased.

    // Helper: we cannot call internal getters for credit, so we infer recorded credit by doing a deposit of 0 and then calling withdrawAll
    // in a separate observation step would consume credit; instead we observe credit by performing a small sequence:
    // - deposit(x) to set a baseline
    // - then call deposit(0) (noop) to leave state unchanged
    // - The only public observables are address(c).balance and address(this).balance. To infer credit we use the following trick:
    //   If we deposit an amount A and immediately withdrawAll(), then if withdrawAll() succeeds the test contract receives up to A back.
    //   So we can measure credit by doing deposit(A) and then calling withdrawAll() and observing how much Ether returns.
    // To avoid actually consuming credit during observation, we will make two independent sequences starting from fresh contract state
    // within the single transaction is required; but C is fresh at deployment so we can do: deposit(a); balanceBefore=address(this).balance; c.withdrawAll(); balanceAfter=address(this).balance; returned = balanceAfter - balanceBefore;
    // That consumes credit, so to get prior credit we instead compare before and after around the specific operation under test.

    // Simplify: We'll assert that performing withdrawAll() cannot increase the recorded credit compared to immediately after a deposit by this contract.
    // Implementation: deposit(a); read address(c).balance as bc1; then optionally call withdrawAll(); then deposit(b); read address(c).balance as bc2.
    // The rule: bc2 <= bc1 + b (i.e., withdrawAll cannot have created extra credit beyond deposits). This uses only public address(c).balance.

    function run(uint a, uint b, bool callWithdrawBefore) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a) + (b)); require(a <= 1000000000000000000000000000000); require(b <= 1000000000000000000000000000000);
        require(address(this).balance >= a + b);
        // deposit first amount a
        c.deposit{value: a}(); if (__ESBMC_reverted()) return;
        uint cBalAfterA = address(c).balance;

        // optionally call withdrawAll() which may transfer Ether back to this contract
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // deposit second amount b
        c.deposit{value: b}(); if (__ESBMC_reverted()) return;
        uint cBalAfterB = address(c).balance;

        // General rule: after depositing b, the contract's balance cannot exceed previous balance plus b.
        // In words: withdrawAll (or any call sequence) cannot create extra Ether in C beyond what was already there plus new deposits.
        // This detects bugs that would mint Ether into C during withdrawAll.
        assert(cBalAfterB <= cBalAfterA + b);
    }

    receive() external payable {}
}

