// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 a, uint256 b, bool callWithdrawBefore) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        b = bound(b, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= a + b);
        try c.deposit{value: a}() {} catch { return; }
        uint cBalAfterA = address(c).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        try c.deposit{value: b}() {} catch { return; }
        uint cBalAfterB = address(c).balance;
        assertTrue(cBalAfterB <= cBalAfterA + b);
    }

    function testFuzz_run(uint256 a, uint256 b, bool callWithdrawBefore) public {
        _run(a, b, callWithdrawBefore);
    }

    receive() external payable {}
}
